// machines/plaits: ASYM-TRI's sample loops (engines/waveshaping.c), hand-written SISD kernels.
// Generated by lib/gen_ws_kernel.py; do not edit by hand.
//
// slope_kernel(Slope *s, const float *k, float *out, int size): slope_render's loop; k[0..1] = the increments of
//   frequency_ and pw_. Writes out and the state back.
// ws_kernel(WS *s, const float *k, float *out, float *aux, int size): ws_render's loop; k[0..2] = the increments of
//   previous_shape_, previous_wavefolder_gain_, previous_overtone_gain_; k[3..7] = the five waveshaper tables
//   (ws_table 0..4), k[8] = lut_fold + 1, k[9] = lut_fold_2 + 1, k[10] = lut_sine (addresses). out and aux hold the two
//   slopes on entry and receive the folded output and the overtone mix.
// Both bit-identical to selcc's code of the C (-DPL_WS_C) (tests/plaits/test_ws_kernel.py).
//
// State on return: R0-R8, R12, I4 and the flags change; every other register is as on entry (R9-R11, R13-R15 saved
// above I7; I0, I1, I2, M6, L0, L1, L2, L4 pushed through R0, M6 = 1 and L0 = L1 = L2 = L4 = 0 set here). No SIMD.
// ABI: as the other kernels (lib/wavetable_sm.s). Assembled under .COMPRESS; integer additions in their 48-bit form.

.SECTION/PM seg_pmco;
.GLOBAL slope_kernel.;
.GLOBAL ws_kernel.;
.COMPRESS;

slope_kernel.:
    R0 = I0;
    DM(I7, M7) = R0;
    R0 = I1;
    DM(I7, M7) = R0;
    R0 = I2;
    DM(I7, M7) = R0;
    R0 = M6;
    DM(I7, M7) = R0;
    R0 = L0;
    DM(I7, M7) = R0;
    R0 = L1;
    DM(I7, M7) = R0;
    R0 = L2;
    DM(I7, M7) = R0;
    R0 = L4;
    DM(I7, M7) = R0;
    M6 = 1;
    L0 = 0;
    L1 = 0;
    L2 = 0;
    L4 = 0;
    I7=MODIFY (I7,-12)(NW);
    DM(1, I7) = R9;
    DM(2, I7) = R10;
    DM(3, I7) = R11;
    DM(4, I7) = R13;
    DM(5, I7) = R14;
    DM(6, I7) = R15;
    I2 = R4;                                            // s
    I4 = R8;                                            // k
    I0 = R12;                                           // out
    R0 = DM(0, I4);
    DM(7, I7) = R0;
    R0 = DM(1, I4);
    DM(8, I7) = R0;
    R0 = DM(1, I6);                                     // size
    DM(9, I7) = R0;
    R15 = DM(0, I2);                                    // phase_
    R14 = DM(1, I2);                                    // next_sample_
    R11 = DM(4, I2);                                    // high_
    R10 = DM(5, I2);                                    // frequency_
    R9 = DM(6, I2);                                     // pw_
    R1 = 0;
    COMP(R0, R1);
    IF LE JUMP _slk_done;
_slk_loop:
    R13 = PASS R14;                                     // this_sample = next_sample
    R14 = 0;                                            // next_sample = 0.0f
    R0 = DM(7, I7);
    F10 = F10 + F0;                                     // frequency = fm.Next()
    R0 = DM(8, I7);
    F9 = F9 + F0;                                       // pw = pwm.Next()
    F15 = F15 + F10;                                    // phase_ += frequency
    R0 = 0x3F800000;                                    // one
    R3 = 0x40000000;                                    // two
    R7 = 0x40000000;                                    // two
    F4 = F0 - F9;                                       // 1.0f - pw
    F1 = RECIPS F9;                                     // slope_up = 1.0f / pw, slope_down = 1.0f / (1.0f - pw)
    F5 = RECIPS F4;
    F2 = F9 * F1;
    F6 = F4 * F5;
    F2 = F3 - F2;
    F6 = F7 - F6;
    F1 = F1 * F2;
    F5 = F5 * F6;
    F2 = F9 * F1;
    F6 = F4 * F5;
    F2 = F3 - F2;
    F6 = F7 - F6;
    F1 = F1 * F2;
    F5 = F5 * F6;
    F3 = F0 * F1;
    F7 = F0 * F5;
    F2 = F9 * F3;
    F6 = F4 * F7;
    F2 = F0 - F2;
    F6 = F0 - F6;
    F2 = F2 * F1;
    F6 = F6 * F5;
    F3 = F3 + F2;
    F7 = F7 + F6;
    DM(10, I7) = R3;
    DM(11, I7) = R7;
    R1 = 0;
    R2 = 1;
    COMP(F15, F9);                                      // phase_ < pw
    IF LT R1 = R2 OR R2;
    COMP(R1, R11);
    IF EQ JUMP _slk_n1;
    DM(12, I7) = R1;                                    // (the new high_)
    F1 = F15 - F9;                                      // t = (phase_ - pw) / frequency
    R4 = 0x40000000;                                    // two
    F5 = RECIPS F10;
    F6 = F10 * F5;                                      // selcc division
    F6 = F4 - F6;
    F5 = F5 * F6;
    F6 = F10 * F5;
    F6 = F4 - F6;
    F5 = F5 * F6;
    F4 = F1 * F5;
    F6 = F10 * F4;
    F6 = F1 - F6;
    F6 = F6 * F5;
    F2 = F4 + F6;
    R0 = DM(10, I7);
    R1 = DM(11, I7);
    F8 = F0 + F1;                                       // discontinuity = (slope_up + slope_down) * frequency
    F8 = F8 * F10;
    R1 = 0x3F800000;                                    // one
    F3 = F1 - F2;                                       // this_sample -= ThisIntegratedBlepSample(t) * discontinuity
    R0 = 0x3F000000;                                    // half
    F4 = F0 * F3;                                       // t1 = 0.5f * t
    F5 = F4 * F4;                                       // t2
    F7 = F5 * F5;                                       // t4
    R0 = 0x3E400000;                                    // 0.1875
    F4 = F0 - F4;
    R0 = 0x3FC00000;                                    // 1.5
    F5 = F0 * F5;
    F4 = F4 + F5;
    F1 = F4 - F7;
    F1 = F1 * F8;
    F13 = F13 - F1;
    R0 = 0x3F000000;                                    // half
    F4 = F0 * F2;                                       // t1 = 0.5f * t
    F5 = F4 * F4;                                       // t2
    F7 = F5 * F5;                                       // t4
    R0 = 0x3E400000;                                    // 0.1875
    F4 = F0 - F4;
    R0 = 0x3FC00000;                                    // 1.5
    F5 = F0 * F5;
    F4 = F4 + F5;
    F1 = F4 - F7;
    F1 = F1 * F8;                                       // next_sample -= NextIntegratedBlepSample(t) * discontinuity
    F14 = F14 - F1;
    R11 = DM(12, I7);                                   // high_ = phase_ < pw
_slk_n1:
    R0 = 0x3F800000;                                    // one
    COMP(F15, F0);                                      // phase_ >= 1.0f
    IF LT JUMP _slk_n2;
    F15 = F15 - F0;
    R4 = 0x40000000;                                    // two
    F5 = RECIPS F10;
    F6 = F10 * F5;                                      // t = phase_ / frequency
    F6 = F4 - F6;
    F5 = F5 * F6;
    F6 = F10 * F5;
    F6 = F4 - F6;
    F5 = F5 * F6;
    F4 = F15 * F5;
    F6 = F10 * F4;
    F6 = F15 - F6;
    F6 = F6 * F5;
    F2 = F4 + F6;
    R0 = DM(10, I7);
    R1 = DM(11, I7);
    F8 = F0 + F1;
    F8 = F8 * F10;
    R1 = 0x3F800000;                                    // one
    F3 = F1 - F2;                                       // this_sample += ThisIntegratedBlepSample(t) * discontinuity
    R0 = 0x3F000000;                                    // half
    F4 = F0 * F3;                                       // t1 = 0.5f * t
    F5 = F4 * F4;                                       // t2
    F7 = F5 * F5;                                       // t4
    R0 = 0x3E400000;                                    // 0.1875
    F4 = F0 - F4;
    R0 = 0x3FC00000;                                    // 1.5
    F5 = F0 * F5;
    F4 = F4 + F5;
    F1 = F4 - F7;
    F1 = F1 * F8;
    F13 = F13 + F1;
    R0 = 0x3F000000;                                    // half
    F4 = F0 * F2;                                       // t1 = 0.5f * t
    F5 = F4 * F4;                                       // t2
    F7 = F5 * F5;                                       // t4
    R0 = 0x3E400000;                                    // 0.1875
    F4 = F0 - F4;
    R0 = 0x3FC00000;                                    // 1.5
    F5 = F0 * F5;
    F4 = F4 + F5;
    F1 = F4 - F7;
    F1 = F1 * F8;                                       // next_sample += NextIntegratedBlepSample(t) * discontinuity
    F14 = F14 + F1;
    R11 = 1;                                            // high_ = 1
_slk_n2:
    R0 = 0;
    COMP(R11, R0);                                      // high_ ? phase_ * slope_up : 1.0f - (phase_ - pw) * slope_down
    IF EQ JUMP _slk_lo;
    R1 = DM(10, I7);
    F1 = F15 * F1;
    JUMP _slk_ns;
_slk_lo:
    R2 = DM(11, I7);
    F1 = F15 - F9;
    F1 = F1 * F2;
    R2 = 0x3F800000;                                    // one
    F1 = F2 - F1;
_slk_ns:
    F14 = F14 + F1;                                     // next_sample += ..
    R0 = 0x40000000;                                    // two
    F0 = F0 * F13;                                      // *out++ = 2.0f * this_sample - 1.0f
    R1 = 0x3F800000;                                    // one
    F0 = F0 - F1;
    DM(I0, M6) = R0;
    R0 = DM(9, I7);
    R1 = 1;
    .NOCOMPRESS;
    R0 = R0 - R1;
    .COMPRESS;
    DM(9, I7) = R0;
    IF NE JUMP _slk_loop;
_slk_done:
    DM(0, I2) = R15;
    DM(1, I2) = R14;
    DM(4, I2) = R11;
    DM(5, I2) = R10;
    DM(6, I2) = R9;
    R9 = DM(1, I7);
    R10 = DM(2, I7);
    R11 = DM(3, I7);
    R13 = DM(4, I7);
    R14 = DM(5, I7);
    R15 = DM(6, I7);
    I7=MODIFY (I7,12)(NW);
    L4 = DM(1, I7);
    L2 = DM(2, I7);
    L1 = DM(3, I7);
    L0 = DM(4, I7);
    M6 = DM(5, I7);
    I2 = DM(6, I7);
    I1 = DM(7, I7);
    I0 = DM(8, I7);
    I12 = DM(M7, I6);
    JUMP (M14, I12) (DB);
    RFRAME;
    NOP;

ws_kernel.:
    R0 = I0;
    DM(I7, M7) = R0;
    R0 = I1;
    DM(I7, M7) = R0;
    R0 = I2;
    DM(I7, M7) = R0;
    R0 = M6;
    DM(I7, M7) = R0;
    R0 = L0;
    DM(I7, M7) = R0;
    R0 = L1;
    DM(I7, M7) = R0;
    R0 = L2;
    DM(I7, M7) = R0;
    R0 = L4;
    DM(I7, M7) = R0;
    M6 = 1;
    L0 = 0;
    L1 = 0;
    L2 = 0;
    L4 = 0;
    I7=MODIFY (I7,-22)(NW);
    DM(1, I7) = R9;
    DM(2, I7) = R10;
    DM(3, I7) = R11;
    DM(4, I7) = R13;
    DM(5, I7) = R14;
    DM(6, I7) = R15;
    I2 = R4;                                            // s
    I4 = R8;                                            // k
    I0 = R12;                                           // out
    R0 = DM(1, I6);                                     // aux
    I1 = R0;
    R0 = DM(0, I4);
    DM(7, I7) = R0;
    R0 = DM(1, I4);
    DM(8, I7) = R0;
    R0 = DM(2, I4);
    DM(9, I7) = R0;
    R0 = DM(3, I4);
    DM(10, I7) = R0;
    R0 = DM(4, I4);
    DM(11, I7) = R0;
    R0 = DM(5, I4);
    DM(12, I7) = R0;
    R0 = DM(6, I4);
    DM(13, I7) = R0;
    R0 = DM(7, I4);
    DM(14, I7) = R0;
    R0 = DM(8, I4);
    DM(15, I7) = R0;
    R0 = DM(9, I4);
    DM(16, I7) = R0;
    R0 = DM(10, I4);
    DM(17, I7) = R0;
    R0 = DM(2, I6);                                     // size
    DM(18, I7) = R0;
    R13 = 0x4B000000;                                   // 2^23
    R1 = 0;
    COMP(R0, R1);
    IF LE JUMP _wsk_done;
_wsk_loop:
    R0 = DM(14, I2);
    R1 = DM(7, I7);
    F0 = F0 + F1;                                       // shape = shape_modulation.Next() * 3.9999f
    DM(14, I2) = R0;
    R1 = 0x407FFE5D;                                    // 3.9999
    F0 = F0 * F1;
    R9 = TRUNC F0;                                      // shape_integral
    R1 = R13 OR R9;
    F1 = F1 - F13;
    F0 = F0 - F1;                                       // shape_fractional
    DM(19, I7) = R0;
    R0 = 0;
    .NOCOMPRESS;
    R0 = R9 + R0;
    .COMPRESS;
    R10 = DM(14, I7);                                   // ws_table: lut_ws_double_bump unless 0..3
    R1 = 0;
    COMP(R0, R1);
    IF LT JUMP _wst10;
    R1 = 3;
    COMP(R0, R1);
    IF GT JUMP _wst10;
    R0 = LSHIFT R0 BY 2;                                // (the frame is byte-addressed)
    R1 = I7;
    .NOCOMPRESS;
    R0 = R0 + R1;
    .COMPRESS;
    I4 = R0;
    R1 = 0;                                             // (DAG gap)
    R1 = 0;
    R1 = 0;
    R10 = DM(10, I4);                                   // k[3 + i] on the frame
_wst10:
    R0 = 1;
    .NOCOMPRESS;
    R0 = R9 + R0;
    .COMPRESS;
    R11 = DM(14, I7);                                   // ws_table: lut_ws_double_bump unless 0..3
    R1 = 0;
    COMP(R0, R1);
    IF LT JUMP _wst11;
    R1 = 3;
    COMP(R0, R1);
    IF GT JUMP _wst11;
    R0 = LSHIFT R0 BY 2;                                // (the frame is byte-addressed)
    R1 = I7;
    .NOCOMPRESS;
    R0 = R0 + R1;
    .COMPRESS;
    I4 = R0;
    R1 = 0;                                             // (DAG gap)
    R1 = 0;
    R1 = 0;
    R11 = DM(10, I4);                                   // k[3 + i] on the frame
_wst11:
    R0 = DM(I0, M5);
    R1 = 0x42FE0000;                                    // 127
    F0 = F1 * F0;                                       // ws_index = 127.0f * out[i] + 128.0f
    R1 = 0x43000000;                                    // 128
    F0 = F0 + F1;
    R14 = 0;                                            // ws_index_integral = 0
    R15 = 0;                                            // ws_index_fractional = 0.0f
    R1 = 0xCB000000;                                    // -2^23
    COMP(F0, F1);                                       // ws_index > -8388608.0f && ws_index < 8388608.0f
    IF LE JUMP _wsk_i2;
    R1 = 0x4B000000;                                    // 2^23
    COMP(F0, F1);
    IF GE JUMP _wsk_i2;
    R14 = TRUNC F0;
    R1 = 0;
    COMP(R14, R1);                                      // itof_small: i < 0 ? -itof_nonneg(-i) : itof_nonneg(i)
    IF GE JUMP _wsk_ip;
    R1 = -R14;
    R1 = R13 OR R1;
    F1 = F1 - F13;
    F1 = -F1;
    JUMP _wsk_id;
_wsk_ip:
    R1 = R13 OR R14;
    F1 = F1 - F13;
_wsk_id:
    F15 = F0 - F1;                                      // ws_index_fractional
    JUMP _wsk_i4;
_wsk_i2:
    R1 = 0xCF000000;                                    // -2^31
    COMP(F0, F1);                                       // ws_index >= -2^31 && ws_index < 2^31: integral only
    IF LT JUMP _wsk_i4;
    R1 = 0x4F000000;                                    // 2^31
    COMP(F0, F1);
    IF GE JUMP _wsk_i4;
    R14 = TRUNC F0;
_wsk_i4:
    R1 = 255;
    R14 = R14 AND R1;                                   // ws_index_integral &= 255
    R0 = LSHIFT R14 BY 2;
    .NOCOMPRESS;
    R1 = R10 + R0;
    .COMPRESS;
    I4 = R1;
    .NOCOMPRESS;
    R2 = R11 + R0;
    .COMPRESS;
    R3 = 0;                                             // (DAG gap)
    R4 = 0;
    R5 = 0;
    R0 = DM(0, I4);                                     // x0
    R1 = DM(1, I4);                                     // x1
    I4 = R2;
    F1 = F1 - F0;                                       // x = x0 + (x1 - x0) * ws_index_fractional
    F1 = F1 * F15;
    F1 = F0 + F1;
    R4 = 0;                                             // (DAG gap)
    R2 = DM(0, I4);                                     // y0
    R3 = DM(1, I4);                                     // y1
    F3 = F3 - F2;                                       // y = y0 + (y1 - y0) * ws_index_fractional
    F3 = F3 * F15;
    F3 = F2 + F3;
    R4 = DM(19, I7);
    F3 = F3 - F1;                                       // mix = x + (y - x) * shape_fractional
    F3 = F3 * F4;
    F3 = F1 + F3;
    R0 = DM(15, I2);
    R1 = DM(8, I7);
    F0 = F0 + F1;                                       // index = mix * wf_gain_modulation.Next() + 0.5f
    DM(15, I2) = R0;
    F3 = F3 * F0;
    R1 = 0x3F000000;                                    // half
    F3 = F3 + F1;
    DM(21, I7) = R3;
    R1 = DM(21, I7);
    R2 = 0;
    COMP(F1, F2);                                       // if (!(index >= 0.0f)) index = 0.0f; else if (index > 1.0f) index = 1.0f
    IF LT R1 = R2 OR R2;
    R2 = 0x3F800000;                                    // one
    COMP(F1, F2);
    IF GT R1 = R2 OR R2;
    R2 = 0x44000000;                                    // 512
    F1 = F1 * F2;                                       // index *= size
    R2 = TRUNC F1;                                      // index_integral
    R3 = R13 OR R2;
    F3 = F3 - F13;
    F8 = F1 - F3;                                       // f = index_fractional
    R2 = LSHIFT R2 BY 2;
    R3 = DM(15, I7);
    .NOCOMPRESS;
    R2 = R2 + R3;
    .COMPRESS;
    I4 = R2;
    R6 = 0x3F000000;                                    // half
    R3 = 0;                                             // (DAG gap)
    R4 = DM(-1, I4);                                    // xm1
    R5 = DM(0, I4);                                     // x0
    R1 = DM(1, I4);                                     // x1
    R7 = DM(2, I4);                                     // x2
    F0 = F1 - F4;                                       // c = (x1 - xm1) * 0.5f
    F0 = F0 * F6;
    F1 = F5 - F1;                                       // v = x0 - x1
    F2 = F0 + F1;                                       // w = c + v
    F3 = F7 - F5;                                       // a = w + v + (x2 - x0) * 0.5f
    F3 = F3 * F6;
    F4 = F2 + F1;
    F3 = F4 + F3;
    F2 = F2 + F3;                                       // b_neg = w + a
    F3 = F3 * F8;                                       // (((a * f) - b_neg) * f + c) * f + x0
    F3 = F3 - F2;
    F3 = F3 * F8;
    F3 = F3 + F0;
    F3 = F3 * F8;
    F0 = F3 + F5;
    DM(22, I7) = R0;                                    // fold
    R1 = DM(21, I7);
    R2 = 0;
    COMP(F1, F2);                                       // if (!(index >= 0.0f)) index = 0.0f; else if (index > 1.0f) index = 1.0f
    IF LT R1 = R2 OR R2;
    R2 = 0x3F800000;                                    // one
    COMP(F1, F2);
    IF GT R1 = R2 OR R2;
    R2 = 0x44000000;                                    // 512
    F1 = F1 * F2;                                       // index *= size
    R2 = TRUNC F1;                                      // index_integral
    R3 = R13 OR R2;
    F3 = F3 - F13;
    F8 = F1 - F3;                                       // f = index_fractional
    R2 = LSHIFT R2 BY 2;
    R3 = DM(16, I7);
    .NOCOMPRESS;
    R2 = R2 + R3;
    .COMPRESS;
    I4 = R2;
    R6 = 0x3F000000;                                    // half
    R3 = 0;                                             // (DAG gap)
    R4 = DM(-1, I4);                                    // xm1
    R5 = DM(0, I4);                                     // x0
    R1 = DM(1, I4);                                     // x1
    R7 = DM(2, I4);                                     // x2
    F0 = F1 - F4;                                       // c = (x1 - xm1) * 0.5f
    F0 = F0 * F6;
    F1 = F5 - F1;                                       // v = x0 - x1
    F2 = F0 + F1;                                       // w = c + v
    F3 = F7 - F5;                                       // a = w + v + (x2 - x0) * 0.5f
    F3 = F3 * F6;
    F4 = F2 + F1;
    F3 = F4 + F3;
    F2 = F2 + F3;                                       // b_neg = w + a
    F3 = F3 * F8;                                       // (((a * f) - b_neg) * f + c) * f + x0
    F3 = F3 - F2;
    F3 = F3 * F8;
    F3 = F3 + F0;
    F3 = F3 * F8;
    F0 = F3 + F5;
    F9 = -F0;                                           // fold_2 = -InterpolateHermite(..)
    R0 = DM(I1, M5);
    R1 = 0x3E800000;                                    // q
    F0 = F0 * F1;
    R1 = 0x3F000000;                                    // half
    F0 = F0 + F1;
    R2 = 0;
    R1 = 0x4B000000;                                    // 2^23
    COMP(F0, F1);                                       // Sine: !(phase >= 0 && phase < 2^23): phase = 0
    IF GE R0 = R2 OR R2;
    COMP(F0, F2);
    IF LT R0 = R2 OR R2;
    R1 = TRUNC F0;                                      // phase -= itof_nonneg((int)phase)
    R1 = R13 OR R1;
    F1 = F1 - F13;
    F0 = F0 - F1;
    R1 = 0x44000000;                                    // 512
    F0 = F0 * F1;                                       // phase *= 512.0f
    R2 = TRUNC F0;
    R3 = R13 OR R2;
    F3 = F3 - F13;
    F3 = F0 - F3;                                       // phase_fractional
